import khMark from '@admin/assets/brand/kh-mark.png';
import { cn } from '@admin/shared/lib/cn';

/**
 * The Kulatissa Hardware "KH" mark, the same artwork as the app icon (generated by build/appicon.swift;
 * don't edit the PNG by hand). Decorative: it always sits beside the store name, so it has no alt text.
 */
export function BrandMark({ className }: { className?: string }) {
    return (
        <img
            src={khMark}
            alt=""
            draggable={false}
            className={cn('size-8 shrink-0 select-none', className)}
        />
    );
}
